// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    // fuzzed params: actor address, deposit amount, withdraw amount, and an offset to set unlockTime
    function testFuzz_property(address actor, uint256 deposit, uint256 withdraw, uint64 offset) public {
        vm.assume(deposit <= VALUE_CAP);
        // keep amounts in reasonable ranges
        deposit = bound(deposit, 1 wei, 10 ether);
        withdraw = bound(withdraw, 0 wei, 10 ether);
        vm.assume(actor != address(0));

        // 1) Prepare actor with funds
        vm.deal(actor, deposit);

        // 2) Actor calls Put via fallback so LogFile gets set already by constructor; use actor as msg.sender
        vm.startPrank(actor);
        // choose an unlock time: current block.timestamp + offset
        uint256 unlock = block.timestamp + uint256(offset);
        // Put must be payable
        c.Put{value: deposit}(unlock);
        vm.stopPrank();

        // read holder struct via public getter Acc(address)
        (uint256 uBefore, uint256 balBefore) = c.Acc(actor);
        // ensure the recorded unlock equals what we set (sanity)
        // If not equal, still continue; we will test property at exact unlock time

        // 3) Warp to exactly the holder's unlock time
        vm.warp(uBefore);

        // 4) Attempt Collect at timestamp == unlockTime. Capture whether the call succeeded
        bool ok;
        vm.startPrank(actor);
        try c.Collect{value: 0}(withdraw) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // 5) After the call, read the holder state for this actor again
        (uint256 uAfter, uint256 balAfter) = c.Acc(actor);

        // GENERAL RULE: In the reference C, calling Collect exactly at block.timestamp == acc.unlockTime MUST NOT decrease the holder's balance (Collect requires block.timestamp > acc.unlockTime).
        // Therefore, for the reference contract, balAfter must always equal balBefore (regardless of ok flag). The mutant that changes the check to >= will allow ok==true and balAfter < balBefore for some inputs.
        assertTrue(balAfter == balBefore);
    }
}
